%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
% retrieve selected cuts used for further fitting
GH_FFCutsFits = recover_selected_cuts('GH_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

fit_res_field = 'all_fit_par';
separate_fig  = false; % if true, detach figures from live script
%%
[S_op110,J_op110,G_op110,Sq_op110,proj110minFF]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:88cf6106] %[output:22c7031a] %[output:91fa31ea] %[output:9e53076b]
    'off110GHminFF',' <110> min FF change',fit_res_field,separate_fig); %[output:group:88cf6106] %[output:22c7031a] %[output:91fa31ea] %[output:9e53076b]

[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    GH_FFCutsFits.(['Ei800_off200GHmaxFF_',fit_res_field]));

proj200maxFF = GH_FFCutsFits.Ei200_off200GHmaxFF.data.proj;
plot_fp(separate_fig,'min FF change for low dE max FF for Ei800', ... %[output:group:3bf336b2] %[output:5eaeb6c4] %[output:5d5561d8] %[output:7d919e7d]
    [S_op110,S_maEi800], ... %[output:5eaeb6c4] %[output:5d5561d8] %[output:7d919e7d]
    [J_op110,J_maEi800], ... %[output:5eaeb6c4] %[output:5d5561d8] %[output:7d919e7d]
    [G_op110,Gam_maEi800]); %[output:group:3bf336b2] %[output:5eaeb6c4] %[output:5d5561d8] %[output:7d919e7d]
%%
bg_dataEi200 = extract_bg_par(GH_FFCutsFits.(['Ei200_off110GHminFF_',fit_res_field]),1);
bg_dataEi400 = extract_bg_par(GH_FFCutsFits.(['Ei400_off110GHminFF_',fit_res_field]),1);
bg_dataEi800mi = extract_bg_par(GH_FFCutsFits.(['Ei800_off110GHminFF_',fit_res_field]),1);
bg_dataEi800ma = extract_bg_par(GH_FFCutsFits.(['Ei800_off200GHmaxFF_',fit_res_field]),1);

plot_fp(separate_fig,'line-q fit bg for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataEi200,bg_dataEi400,bg_dataEi800mi,bg_dataEi800ma]) %[output:group:981d7022] %[output:2956d259]
%%
spp.Ei200_off110GHminNbg = GH_FFCutsFits.Ei200_off110GHminFF - ...
    sqw_eval(GH_FFCutsFits.Ei200_off110GHminFF,@linterp_bg,bg_dataEi200);
plot(spp.Ei200_off110GHminNbg); lz 0 1; keep_figure %[output:503b7858]

spp.Ei400_off110GHminNbg = GH_FFCutsFits.Ei400_off110GHminFF - ...
    sqw_eval(GH_FFCutsFits.Ei400_off110GHminFF,@linterp_bg,bg_dataEi400);
plot(spp.Ei400_off110GHminNbg); lz 0 1; keep_figure %[output:38b7a034]

spp.Ei800_off110GHminNbg = GH_FFCutsFits.Ei800_off110GHminFF - ...
    sqw_eval(GH_FFCutsFits.Ei800_off110GHminFF,@linterp_bg,bg_dataEi800mi);
plot(spp.Ei800_off110GHminNbg); lz 0 1; keep_figure %[output:3720a811]

spp.Ei800_off200GHmaxNbg = GH_FFCutsFits.Ei800_off200GHmaxFF - ...
    sqw_eval(GH_FFCutsFits.Ei800_off200GHmaxFF,@linterp_bg,bg_dataEi800ma);
plot(spp.Ei800_off200GHmaxNbg); lz 0 0.1; keep_figure %[output:1d5707af]
%%


%%
cuts_rangesGH = containers.Map();
cuts_rangesGH('Ei200_off110GHminNbg')  = [0;100];
cuts_rangesGH('Ei400_off110GHminNbg') = [100;120];
cuts_rangesGH('Ei800_off110GHminNbg') = [120;170];
cuts_rangesGH('Ei800_off200GHmaxNbg') = [170;400];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_rangesGH,[0,0.03,1],false); %[output:63b7c316] %[output:2f719bc9]
data_ranges = cuts_rangesGH.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('GH_100_data','pan_data');
fh.UserData = w2.data;
%%
gamma=10;Seff0=0.7917;

J0=39; J1=35;
correct_ff = 1;
gap = 0;    %
init_fg_param = [correct_ff,8,gamma,Seff0,  0,   J0, J1,  0,  0,  0];

kk = tobyfit(spp.Ei800_off200GHmaxNbg);
kk = kk.set_fun(@sqw_iron);
hkl_proj = spp.Ei800_off200GHmaxNbg.data.proj;

%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];

kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);


%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);


[fit_obj,fit_par] = kk.fit(); %[output:8e7bff83] %[output:74bb272e]
%%

plot(spp.Ei800_off200GHmaxNbg); lz 0 0.1;keep_figure; %[output:569eea8e]
plot(fit_obj); lz 0 0.1;keep_figure; %[output:675a186a]
%[fit_obj,fit_par] = kk.simulate();
%%
if ~exist('magi','var')
    magi = MagneticIons();
end
spp.Ei200_off110GHminNbg= magi.correct_mag_ff(spp.Ei200_off110GHminNbg);
plot(spp.Ei200_off110GHminNbg); lz 0 1;keep_figure; %[output:76e25368]

spp.Ei400_off110GHminNbg = magi.correct_mag_ff(spp.Ei400_off110GHminNbg);
plot(spp.Ei400_off110GHminNbg); lz 0 2; keep_figure %[output:2160d809]

spp.Ei800_off110GHminNbg = magi.correct_mag_ff(spp.Ei800_off110GHminNbg);
plot(spp.Ei800_off110GHminNbg); lz 0 2; keep_figure %[output:515e4bc4]

spp.Ei800_off200GHmaxNbg = magi.correct_mag_ff(spp.Ei800_off200GHmaxNbg);
plot(spp.Ei800_off200GHmaxNbg); lz 0 2; keep_figure %[output:552bc267]

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_rangesGH,[0,0.03,1],false); %[output:3192a9ef] %[output:486800d7]
data_ranges = cuts_rangesGH.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
save('GH_100_data','pan_data');

